using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

// Reproducible synthetic fixture. Each implementation stage writes separate receipts.
static class ResponsivenessBaseline {
 [DllImport("user32.dll")]static extern int GetWindowLong(IntPtr window,int index);
 [DllImport("user32.dll")]static extern int SetWindowLong(IntPtr window,int index,int value);
 static void NoActivate(Form form){form.ShowInTaskbar=false;SetWindowLong(form.Handle,-20,GetWindowLong(form.Handle,-20)|0x08000000);}
 [DllImport("user32.dll")]static extern uint GetGuiResources(IntPtr process,uint flags);
 static string output;
 static readonly Dictionary<string,object> result=new Dictionary<string,object>();
 static T Field<T>(object target,string name){return (T)target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);}
 static void Set(object target,string name,object value){target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);}
 static void Call(object target,string name,params object[] args){target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,args);}
 static void Write(string state){result["status"]=state;result["updated_utc"]=DateTime.UtcNow.ToString("o");File.WriteAllText(output,J.Json().Serialize(result));}
 static void Pump(Func<bool> done,int milliseconds=12000){var clock=Stopwatch.StartNew();while(!done()&&clock.ElapsedMilliseconds<milliseconds){Application.DoEvents();Thread.Sleep(5);}if(!done())throw new TimeoutException("Fixture UI did not settle");Application.DoEvents();}
 static Dictionary<string,object> Memory(int pid){using(var p=Process.GetProcessById(pid)){p.Refresh();return J.O("pid",pid,"private_bytes",p.PrivateMemorySize64,"working_set",p.WorkingSet64,"peak_working_set",p.PeakWorkingSet64,"handles",p.HandleCount,"cpu_ms",p.TotalProcessorTime.TotalMilliseconds,"managed_bytes_current_gui_only",pid==Process.GetCurrentProcess().Id?GC.GetTotalMemory(false):0,"gdi",GetGuiResources(p.Handle,0),"user",GetGuiResources(p.Handle,1));}}
 static object[] Rows(int count){return Enumerable.Range(0,count).Select(i=>(object)J.O("name","perf-node-"+i,"data",J.O("label","Тестовая машина "+i,"ram_mb",256,"cores",1,"launch_profile","tcg","iso_path","","disk_path","","extra_args",new object[0]),"network_view",J.O("adapters",new object[0]))).ToArray();}
 static object[] Stands(int count,int machines){return Enumerable.Range(0,count).Select(i=>(object)J.O("id","perf-stand-"+i,"name","Синтетический стенд "+i,"revision",1,"members",new object[]{"perf-node-"+(i%machines),"perf-node-"+((i+1)%machines)},"order",new object[]{"perf-node-"+(i%machines),"perf-node-"+((i+1)%machines)},"links",new object[0])).ToArray();}
 static object Catalog(int count){return J.O("online",false,"vm_state","stopped","rows",Enumerable.Range(0,count).Select(i=>(object)J.O("id","point-"+i,"name","Снимок "+i,"date",1700000000+i,"kind","disk","state","ready")).ToArray());}
 sealed class Service:ISnapshotUiService {readonly object catalog;public Service(int count){catalog=Catalog(count);}public bool Supports(string s){return false;}public Task<object> Load(){return Task.FromResult(catalog);}public Task<object> Execute(SnapshotUiRequest request){throw new InvalidOperationException("No mutations in baseline");}public event Action<SnapshotUiProgress> Progress{add{}remove{}}public object Data{get{return catalog;}}}
 static void Render(Control control){using(var bitmap=new Bitmap(Math.Max(1,control.Width),Math.Max(1,control.Height)))control.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));}
 static IEnumerable<Control> All(Control root){foreach(Control child in root.Controls){yield return child;foreach(var item in All(child))yield return item;}}
 static void ReadyDecor(Form root){Pump(()=>All(root).OfType<StateStage>().Where(c=>c.Visible).All(c=>c.BackgroundReady)&&All(root).OfType<ReferenceHeader>().Where(c=>c.Visible).All(c=>c.GhostReady)&&(root.Owner==null||root.Owner.Controls.OfType<ReferenceBackdropSurface>().All(c=>c.Snapshot!=null)),20000);}
 static object Times(List<double> values){var sorted=values.OrderBy(v=>v).ToArray();return J.O("samples",values.Count,"median_ms",sorted[sorted.Length/2],"p95_ms",sorted[Math.Min(sorted.Length-1,(int)Math.Ceiling(sorted.Length*.95)-1)],"max_ms",sorted.Last());}
 static MainWindow Window(string root,int count,float scale,int width,int height){var main=new MainWindow(root,null,false,false){StartPosition=FormStartPosition.Manual,Location=new Point(-6000,-5000)};if(width>2000)main.MaximumSize=new Size(width+128,height+128);main.ClientSize=new Size(width,height);if(scale!=1)main.Scale(new SizeF(scale,scale));main.ClientSize=new Size(width,height);NoActivate(main);main.Show();Call(main,"Fill",J.O("mode","normal","rows",Rows(count)));main.ApplyStates(Enumerable.Range(0,count).ToDictionary(i=>"perf-node-"+i,i=>(object)"stopped"));Application.DoEvents();return main;}
 static void Matrix(string root,int count,float scale,int width,int height){
  var watch=Stopwatch.StartNew();using(var main=Window(root,count,scale,width,height)){result["actual_client_width"]=main.ClientSize.Width;result["actual_client_height"]=main.ClientSize.Height;result["physical_dpi"]=main.DeviceDpi;result["requested_client_width"]=width;result["requested_client_height"]=height;Render(main);result["cold_shell_ms"]=watch.Elapsed.TotalMilliseconds;ReadyDecor(main);Render(main);watch.Stop();result["cold_construct_show_apply_render_ms"]=watch.Elapsed.TotalMilliseconds;result["memory_after_library"]=Memory(Process.GetCurrentProcess().Id);
   var tabs=Field<WorkspaceTabs>(main,"workspace");var warm=new List<double>();var response=new List<double>();for(int i=0;i<30;i++){watch.Restart();tabs.SelectedIndex=i%2;watch.Stop();response.Add(watch.Elapsed.TotalMilliseconds);watch.Restart();tabs.Refresh();watch.Stop();warm.Add(watch.Elapsed.TotalMilliseconds);}result["tab_handler_ms"]=Times(response);result["tab_forced_render_ms"]=Times(warm);
   int standCount=count==20?10:100;Set(main,"stands",Stands(standCount,count).ToList());Set(main,"standMode",true);watch.Restart();Call(main,"RenderStands");watch.Stop();result["stand_count"]=standCount;result["stand_library_apply_ms"]=watch.Elapsed.TotalMilliseconds;Set(main,"standMode",false);
   foreach(int size in new[]{1000,10000}){var service=new Service(size);watch.Restart();using(var catalog=new SnapshotsWindow(service,"synthetic",service.Data)){if(scale!=1)catalog.Scale(new SizeF(scale,scale));catalog.StartPosition=FormStartPosition.Manual;catalog.Location=new Point(-6000,-5000);NoActivate(catalog);catalog.Show(main);result["catalog_"+size+"_actual_size"]=catalog.ClientSize.ToString();Render(catalog);result["catalog_"+size+"_shell_ms"]=watch.Elapsed.TotalMilliseconds;ReadyDecor(catalog);Render(catalog);watch.Stop();result["catalog_"+size+"_construct_show_apply_render_ms"]=watch.Elapsed.TotalMilliseconds;result["memory_catalog_"+size]=Memory(Process.GetCurrentProcess().Id);catalog.Close();}}
   var stage=Field<StateStage>(main,"machineStage");tabs.SelectedIndex=0;stage.Present("running");var frames=new List<double>();for(int i=0;i<40;i++){watch.Restart();Render(stage);watch.Stop();frames.Add(watch.Elapsed.TotalMilliseconds);Application.DoEvents();Thread.Sleep(16);}result["active_stage_offscreen_paint_ms"]=Times(frames);result["memory_end"]=Memory(Process.GetCurrentProcess().Id);Program.TestMode=true;main.Close();}
 }
 static void Lifecycle(string root){using(var main=Window(root,200,1,1920,1080)){var service=new Service(1000);using(var warm=new SnapshotsWindow(service,"synthetic",service.Data)){warm.Show(main);warm.Close();}result["warm_memory"]=Memory(Process.GetCurrentProcess().Id);var openings=new List<double>();var swaps=new List<double>();
   for(int i=0;i<100;i++){var watch=Stopwatch.StartNew();if(i%2==0){using(var dialog=new SnapshotsWindow(service,"synthetic",service.Data)){dialog.Show(main);Application.DoEvents();dialog.Close();}}else{using(var dialog=new LogsWindow(main,"perf-node-0",true)){dialog.Show(main);Application.DoEvents();dialog.Close();}}watch.Stop();openings.Add(watch.Elapsed.TotalMilliseconds);watch.Restart();Call(main,"SelectVm","perf-node-"+(i%200));Application.DoEvents();watch.Stop();swaps.Add(watch.Elapsed.TotalMilliseconds);if(i%10==0){result["completed_cycles"]=i+1;result["current_memory"]=Memory(Process.GetCurrentProcess().Id);Write("running");}}
   result["open_close_100"]=Times(openings);result["machine_selection_100"]=Times(swaps);result["raw_after_cycles"]=Memory(Process.GetCurrentProcess().Id);GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();result["retained_after_one_diagnostic_gc"]=Memory(Process.GetCurrentProcess().Id);Program.TestMode=true;main.Close();}
 }
 static void Transport(string root){using(var main=Window(root,20,1,1280,800)){var navigation=Field<WorkspaceTabs>(main,"workspace");var rows=new List<object>();foreach(int delay in new[]{0,200,2000}){bool done=false;var watch=Stopwatch.StartNew();main.Read("Fixture delay",()=>{Thread.Sleep(delay);return delay;},value=>done=true,null,"fixture/"+delay);double dispatch=watch.Elapsed.TotalMilliseconds;navigation.SelectedIndex=1;Pump(()=>done);rows.Add(J.O("simulated_backend_delay_ms",delay,"dispatch_ms",dispatch,"total_completion_ms",watch.Elapsed.TotalMilliseconds,"global_busy_during_read",main.Busy,"navigation_preserved",navigation.SelectedIndex==1));}bool failed=false;main.Read("Fixture error",()=>{throw new IOException("Synthetic failure");},null,e=>failed=true,"fixture-error");Pump(()=>failed);result["read_delays"]=rows;result["inline_error_releases_ui"]=!main.Busy;Program.TestMode=true;main.Close();}
 }
 static void Idle(string root,string python,int seconds){
  Program.TestMode=false;var main=new MainWindow(root,python,false,true){StartPosition=FormStartPosition.Manual,Location=new Point(-6000,-5000),ClientSize=new Size(1920,1080)};var timer=new System.Windows.Forms.Timer{Interval=1000};var wall=Stopwatch.StartNew();Stopwatch measured=null;double guiCpu=0,backendCpu=0;var samples=new List<object>();int lastSecond=-1;
  main.Shown+=(s,e)=>timer.Start();timer.Tick+=(s,e)=>{try{if(measured==null){if(main.Busy||main.Backend==null){if(wall.Elapsed.TotalSeconds>40)throw new TimeoutException("Idle fixture startup exceeded 40s");return;}Render(main);guiCpu=Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds;using(var p=Process.GetProcessById(main.Backend.Pid))backendCpu=p.TotalProcessorTime.TotalMilliseconds;measured=Stopwatch.StartNew();result["requested_idle_seconds"]=seconds;result["fixture_backend_pid"]=main.Backend.Pid;}
   int second=(int)measured.Elapsed.TotalSeconds;if(second==lastSecond||second%5!=0&&second<seconds)return;lastSecond=second;var gui=Memory(Process.GetCurrentProcess().Id);var backend=Memory(main.Backend.Pid);samples.Add(J.O("elapsed_seconds",second,"gui",gui,"backend",backend));result["elapsed_idle_seconds"]=second;result["idle_samples"]=samples;result["cpu_percent_machine_gui_plus_backend"]=second>0?((double)gui["cpu_ms"]-guiCpu+(double)backend["cpu_ms"]-backendCpu)/(measured.Elapsed.TotalMilliseconds*Environment.ProcessorCount)*100:0;Write(second>=seconds?"pass":"running");if(second>=seconds){timer.Stop();Program.TestMode=true;main.Close();}
  }catch(Exception error){result["error"]=error.ToString();Write("error");timer.Stop();Program.TestMode=true;main.Close();}};
  NoActivate(main);Application.Run(main);timer.Dispose();main.Dispose();
 }
 [STAThread]static int Main(string[] args){output=args[2];result["scenario"]=args[0];result["started_utc"]=DateTime.UtcNow.ToString("o");result["pid"]=Process.GetCurrentProcess().Id;result["synthetic_only"]=true;result["monitor_fps_measured"]=false;result["cpu_logical_processors"]=Environment.ProcessorCount;
  try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Program.TestMode=false;string mode=args[0];int count=Int32.Parse(args[4]);float scale=Single.Parse(args[5],System.Globalization.CultureInfo.InvariantCulture);result["machines"]=count;result["scale_synthetic"]=scale;result["display_profile"]=args[6];Write("running");
   if(mode=="idle"){Idle(args[1],args[3],Int32.Parse(args[7]));return J.S(result,"status")=="pass"?0:1;}
   if(mode=="matrix")Matrix(args[1],count,scale,args[6]=="4k"?3840:1920,args[6]=="4k"?2160:1080);else if(mode=="lifecycle")Lifecycle(args[1]);else if(mode=="transport")Transport(args[1]);else throw new Exception("Unknown mode");Write("pass");return 0;
  }catch(Exception error){result["error"]=error.ToString();Write("error");return 1;}
 }
}
